// Briefing plugin, contract: 05_daily-briefing/docs/briefing-plugin-spec.md. Plain text only.
// Says nothing on a quiet day (empty: ''), and only an alert when emails are held back.
const rows = $('Read Stopped Emails').all().map((i) => i.json).filter((r) => r && r.message_id);
const section = { key: 'inbox', icon: '📥', title: 'INBOX', summary: '', blocks: [], empty: '' };
if (!rows.length) return [{ json: section }];
const reset = rows.map((r) => r.resets_at).filter(Boolean).sort().pop();
const back = !reset || Date.parse(reset) <= Date.now();
const when = reset ? DateTime.fromISO(reset).setZone('Europe/Zurich').toFormat("dd.MM. HH:mm 'UTC'Z") : '';
const STAGE = { vision: 'attachment reading', classifier: 'classification', extractor: 'invoice extraction', 'contact fill': 'contact update' };
const stage = (r) => STAGE[r.stopped_by] || 'attachment reading';
const stages = [...new Set(rows.map(stage))].join(', ');
const clip = (v, n) => { const s = String(v ?? '').trim(); return s.length > n ? s.slice(0, n - 1) + '…' : s; };
const n = rows.length;
const SHOWN = 3;
section.blocks.push({ level: 'alert', items: [
  n + (n === 1 ? ' email' : ' emails') + ' held back: an LLM daily limit stopped ' + stages + '\n'
  + (back ? 'the quota is back: send /rerun_attachments' : 'send /rerun_attachments after it resets ' + when + ', or change the model') + '\n'
  + rows.slice(0, SHOWN).map((r) => clip(r.subject || '(no subject)', 40) + ' · since ' + String(r.stopped_at || '').slice(0, 10)).join('\n')
  + (n > SHOWN ? '\n+' + (n - SHOWN) + ' more' : ''),
] });
return [{ json: section }];

// One item per held-back email, shaped like the Gmail trigger item the organizer's catch-up entry reads.
return $('Read Stopped Emails').all().map((i) => i.json).filter((r) => r && r.message_id)
  .map((r) => ({ json: { id: r.message_id } }));

// The reply goes out through menu-handler's Send Reply (Markdown), so no _ * ` [ in it.
const clean = (s) => String(s).replace(/[_*`\[\]]/g, '');
const before = $('Read Stopped Emails').all().map((i) => i.json).filter((r) => r && r.message_id);
if (!before.length) return [{ json: { response: 'Nothing is held back.' } }];
const after = $('Read Stopped Again').all().map((i) => i.json).filter((r) => r && r.message_id);
const filed = before.filter((b) => !after.some((a) => a.message_id === b.message_id)).length;
let text = 'Rerun: ' + filed + ' of ' + before.length + ' filed.';
if (after.length) {
  const reset = after.map((r) => r.resets_at).filter(Boolean).sort().pop();
  text += ' Still held back: ' + after.length + ' (' + after.slice(0, 5).map((r) => clean(r.subject || '(no subject)').slice(0, 40)).join('; ') + ').'
    + (reset ? ' Quota resets ' + DateTime.fromISO(reset).setZone('Europe/Zurich').toFormat("dd.MM. HH:mm 'UTC'Z") + '.' : '');
}
return [{ json: { response: text } }];
